package dev.crowncinder.client;
import dev.crowncinder.CrownCinder;import dev.crowncinder.entity.ModEntities;import net.fabricmc.api.ClientModInitializer;import net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry;import net.minecraft.client.render.entity.ZombieEntityRenderer;import net.minecraft.entity.mob.ZombieEntity;import net.minecraft.util.Identifier;
public final class CrownClient implements ClientModInitializer{public void onInitializeClient(){register(ModEntities.GOBLIN,"goblin.png");register(ModEntities.ORC,"orc.png");register(ModEntities.TROLL,"troll.png");register(ModEntities.WEREWOLF,"werewolf.png");register(ModEntities.OGRE,"orc.png");register(ModEntities.MINOTAUR,"troll.png");register(ModEntities.DARK_KNIGHT,"werewolf.png");}private static <T extends ZombieEntity> void register(net.minecraft.entity.EntityType<T> t,String x){EntityRendererRegistry.register(t,c->new ZombieEntityRenderer(c){@Override public Identifier getTexture(ZombieEntity e){return CrownCinder.id("textures/entity/"+x);}});}}
